#include <algorithm>
#include <queue>

class Solution {
public:
    int findMaximizedCapital(int k, int w, vector<int>& profits, vector<int>& capital) {
        int n = profits.size();
        vector<vector<int>> pairs;
        priority_queue<int> max_heap;
        int pointer = 0;

        for (int i = 0; i < n; i++) {
            pairs.push_back({capital[i], profits[i]});
        }

        sort(pairs.begin(), pairs.end());

        while (k > 0) {
            for (int i = pointer; i < n; i++) {
                if (pairs[i][0] > w) break;
                max_heap.push(pairs[i][1]);
                pointer++;
            }

            if (max_heap.empty()) break;
            w += max_heap.top();
            max_heap.pop();
            k--;
        }

        return w;
    }
};

